{
  "states": ["AUTHORIZATION", "TRANSACTION"],
  "transitions": [
    {
      "from": "AUTHORIZATION",
      "event": "USER/PASS or APOP",
      "action": "respond with positive status if authentication succeeds and lock is acquired",
      "to": "TRANSACTION"
    },
    {
      "from": "AUTHORIZATION",
      "event": "QUIT",
      "action": "respond with +OK",
      "to": "CLOSED"
    },
    {
      "from": "AUTHORIZATION",
      "event": "failed authentication or lock acquisition",
      "action": "respond with negative status",
      "to": "AUTHORIZATION"
    }
  ]
}

